export const ICON_NAMES = Object.keys(P);

const safeSize = (n) => {
  const v = Number(n);
  return Number.isFinite(v) && v > 0 ? Math.min(512, Math.round(v)) : 16;
};

const safeClass = (c) => String(c || "").replace(/[^a-zA-Z0-9_\- ]/g, "").trim();

export function iconSvg(name, size = 16, extraClass = "") {
  const body = P[name] || P.circle;
  const s = safeSize(size);
  const cls = safeClass(extraClass);
  // data-icon tags the glyph so CSS can tint and animate individual buttons without
  // touching the path table.
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${s}" height="${s}" viewBox="0 0 256 256" fill="currentColor" data-icon="${safeClass(name)}"${
    cls ? ` class="${cls}"` : ""
  } aria-hidden="true">${body}</svg>`;
}

/** Build an <svg> node. */
export function iconEl(name, size = 16, extraClass = "") {
  const wrap = document.createElement("span");
  wrap.innerHTML = iconSvg(name, size, extraClass).trim();
  return wrap.firstElementChild;
}

/** True when the icon name exists — useful for catching typos during development. */
export const hasIcon = (name) => name in P;
